import ajax from "@/utils/ajax";
import { action, computed, observable, makeObservable } from "mobx";
/**
 * @name 默认规则
 * createdAt 创建时间
 * updatedAt 更新时间
 * 数据库字段
 */
 export interface ColumnItem {
    // 字段描述
    desc?: string;
    // 字段备注
    comment?: string;
    // 字段名称
    key: string;
    // 字段类型
    type?: JSONSchema['type']
    format?: "email" | "url" | "date" | "dateTime";
    // 长度，默认255
    length?: number;
    // 默认值
    default?: any;
    // 字段可选值范围
    enum?: []
}

// 索引
export interface IndexItem {
    // 索引字段
    keys: string[];
}

export interface TableConfig {
    tableName?: string; // 数据表名
    // 主键
    primary: string;
    // 唯一索引
    uniqueKey: string;
    // 数据表说明
    desc?: string;
    column: ColumnItem[];
    // 索引列
    index?: IndexItem[];
    // 数据表对于用户键值 默认 => userId
    ownerKey?: string;
    // 默认使用的sql 链接
    db?: string;
}


/**
 * 数据表管理
 */
class dictStore {
    @observable database: Record<string, TableConfig>;
    @action
    setDatabase = (data) => {
        this.database = data;
    }

    loading = false;

    init = () => {
        if(this.loading) return;
        this.loading = true;
        // 获取数字词典
        return ajax.get('/fetchDataDictionary', {}).then((res) => {
            this.setDatabase(res.data);
        }).finally(() => {
            this.loading = false;
        })
    }

    constructor() {
        makeObservable(this);
    }

    @computed get options(){
        return Object.keys(this.database || {}).map((key) => ({
            value: key,
            label: this.database[key].desc? `${key}(${this.database[key].desc})` : key,
        }))
    }

    getOptions(): any[]{
        if(!this.database) this.init();
        return this.options;
    }

    async getDatabase(){
        if(!this.database){
            await this.init();
        }
        return this.database;
    }


    /**
     * 根据数据表key返回列表集合
     */
    getTables(keys: string[]):TableConfig[] {
        if(!this.database){
            this.init();
            return [];
        }
        let result = Array.from(new Set(['User', 'Role', 'UserRole', ...keys]));
        return result.filter((o) => this.database[o]).map((k) => ({ tableName: k, ...this.database[k] }))
    }
}

export default new dictStore();
